-- Fresh isolated foundation only. Never execute against a legacy database.
PRAGMA application_id = 1312901428;
PRAGMA user_version = 2;
CREATE TABLE workspaces(id TEXT PRIMARY KEY, name TEXT NOT NULL, revision INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, budget_limit INTEGER NOT NULL CHECK(budget_limit>=0), currency TEXT NOT NULL CHECK(currency='CNY'));
CREATE TABLE roles(workspace_id TEXT NOT NULL REFERENCES workspaces(id), principal_id TEXT NOT NULL, role INTEGER NOT NULL CHECK(role BETWEEN 0 AND 3), revision INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(workspace_id,principal_id));
CREATE TABLE objects(workspace_id TEXT NOT NULL REFERENCES workspaces(id), id TEXT NOT NULL, revision INTEGER NOT NULL, deleted INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(workspace_id,id));
CREATE TABLE object_versions(workspace_id TEXT NOT NULL, object_id TEXT NOT NULL, revision INTEGER NOT NULL, sha256 TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(workspace_id,object_id,revision), FOREIGN KEY(workspace_id,object_id) REFERENCES objects(workspace_id,id));
CREATE TABLE sessions(workspace_id TEXT NOT NULL REFERENCES workspaces(id), id TEXT NOT NULL, owner TEXT NOT NULL, epoch INTEGER NOT NULL, stopped INTEGER NOT NULL, revision INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(workspace_id,id));
CREATE TABLE deliveries(workspace_id TEXT NOT NULL, id TEXT NOT NULL, session_id TEXT NOT NULL, epoch INTEGER NOT NULL, object_id TEXT NOT NULL, object_revision INTEGER NOT NULL, object_sha256 TEXT NOT NULL, bundle_sha256 TEXT NOT NULL, recipient TEXT NOT NULL, role_revision INTEGER NOT NULL, expires_tick INTEGER NOT NULL, fence_generation INTEGER NOT NULL, state INTEGER NOT NULL, evidence INTEGER NOT NULL, revision INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,session_id) REFERENCES sessions(workspace_id,id));
CREATE TABLE approvals(workspace_id TEXT NOT NULL, delivery_id TEXT NOT NULL, principal_id TEXT NOT NULL, bundle_sha256 TEXT NOT NULL, role_revision INTEGER NOT NULL, revision INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(workspace_id,delivery_id,principal_id), FOREIGN KEY(workspace_id,delivery_id) REFERENCES deliveries(workspace_id,id));
CREATE TABLE private_cards(workspace_id TEXT NOT NULL, delivery_id TEXT NOT NULL, recipient TEXT NOT NULL, object_sha256 TEXT NOT NULL, revision INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(workspace_id,delivery_id));
CREATE TABLE audit_events(seq INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id TEXT NOT NULL, principal_id TEXT NOT NULL, action TEXT NOT NULL, resource_id TEXT NOT NULL, revision INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE outbox(event_id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, resource_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','dispatching','applied','cancelled','outcome_unknown')), attempts INTEGER NOT NULL CHECK(attempts BETWEEN 0 AND 1), revision INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE command_results(principal_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, command_sha256 TEXT NOT NULL, result BLOB NOT NULL, revision INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(principal_id,idempotency_key));
CREATE TABLE budget_reservations(workspace_id TEXT NOT NULL REFERENCES workspaces(id), id TEXT NOT NULL, principal_id TEXT NOT NULL, reserved_minor INTEGER NOT NULL CHECK(reserved_minor>0), actual_minor INTEGER, status TEXT NOT NULL CHECK(status IN ('reserved','known','unknown','released')), currency TEXT NOT NULL CHECK(currency='CNY'), revision INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(workspace_id,id));
